css:
/* Inner West Sydney Plumbers: home page styles
   Palette taken from the logo: ink navy #0A1B26, pipe orange #FD430E,
   collar orange #D2380F, slate collar #1A2E3C. Everything sits on a light
   concrete "wall" so the 3D pipe run can pass behind the content panels. */

html { scroll-behavior: smooth; scroll-padding-top: 92px; }
body { margin: 0; }

.iwsp {
  --ink: #0A1B26;
  --slate: #1A2E3C;
  --orange: #FD430E;
  --orange-d: #D2380F;
  --white: #FFFFFF;
  --wall: #EEF1F3;
  --line: #D5DCE1;
  --mute: #4A5A66;
  --mute-ink: #B8C4CC;
  --hdr: 76px;
  --wrap: 1240px;
  --gut: clamp(16px, 2.6vw, 32px);
  --gap: 28px;
  --display: "Archivo", "Arial Black", "Helvetica Neue", Arial, sans-serif;
  --body: "Archivo", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  background: var(--wall);
  color: var(--ink);
  font-family: var(--body);
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
}
.iwsp *, .iwsp *::before, .iwsp *::after { box-sizing: border-box; }
.iwsp img { max-width: 100%; height: auto; display: block; }
.iwsp p { margin: 0 0 1em; max-width: 68ch; }
.iwsp p:last-child { margin-bottom: 0; }
.iwsp ul, .iwsp ol { margin: 0; padding: 0; }
.iwsp :focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; border-radius: 4px; }

.iw-skip { position: absolute; left: 12px; top: -80px; z-index: 100; background: var(--ink); color: var(--white); padding: 12px 18px; border-radius: 8px; font-weight: 700; }
.iw-skip:focus { top: 12px; }

.iw-wrap { max-width: var(--wrap); margin-inline: auto; padding-inline: var(--gut); }

/* The fixed 3D canvas is added by scene.js. Content that must sit in front
   of the pipe is positioned with z-index 1. */
.iw-canvas { position: fixed; left: 0; top: 0; width: 100vw; height: 100vh; height: 100lvh; z-index: 0; pointer-events: none; opacity: 0; transition: opacity .7s ease; }
.iw-3d .iw-canvas { opacity: 1; }
.iw-panel, .iw-hero-copy, .iw-cue { position: relative; z-index: 1; }

/* ---------- Type ---------- */
.iw-h1, .iw-h2 { font-family: var(--display); font-weight: 900; font-stretch: 125%; text-transform: uppercase; letter-spacing: -.012em; margin: 0; text-wrap: balance; }
.iw-h1 { font-size: clamp(2.3rem, 4.5vw, 4rem); line-height: .97; margin-bottom: 22px; }
.iw-h2 { font-size: clamp(1.55rem, 2.55vw, 2.35rem); line-height: 1.03; margin-bottom: 18px; }
.iw-h3 { font-family: var(--display); font-weight: 800; font-stretch: 108%; font-size: 1.16rem; line-height: 1.22; margin: 0 0 8px; }
.iw-lead { font-size: clamp(1.06rem, 1.35vw, 1.25rem); line-height: 1.55; color: var(--mute); max-width: 54ch; }
.iw-panel-lead { font-size: 1.1rem; }

.iw-panel p a, .iw-panel li a { color: var(--orange-d); font-weight: 600; text-decoration: underline; text-decoration-thickness: 1.5px; text-underline-offset: 3px; }
.iw-panel p a:hover, .iw-panel li a:hover { color: var(--ink); }

/* ---------- Buttons: shaped like the pipe collars in the logo ---------- */
.iw-btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 54px; padding: 0 28px; border: 0; border-radius: 9px; font-family: var(--display); font-weight: 800; font-stretch: 108%; font-size: 1.02rem; line-height: 1; text-decoration: none; white-space: nowrap; cursor: pointer; transition: background-color .15s ease, color .15s ease, box-shadow .15s ease; }
.iw-btn-sm { min-height: 44px; padding-inline: 20px; font-size: .95rem; }
.iw-ico { width: 1.1em; height: 1.1em; fill: currentColor; flex: none; }
.iw-btn-call { background: var(--orange); color: var(--ink); padding-inline: 36px; box-shadow: inset 10px 0 0 var(--orange-d), inset -10px 0 0 var(--orange-d); }
.iw-btn-call.iw-btn-sm { padding-inline: 26px; box-shadow: inset 8px 0 0 var(--orange-d), inset -8px 0 0 var(--orange-d); }
.iw-btn-call:hover { background: #FF5A2B; }
.iw-btn-call:focus-visible { outline-color: var(--ink); }
.iw-btn-line { background: var(--white); color: var(--ink); box-shadow: inset 0 0 0 2px var(--ink); }
.iw-btn-line:hover { background: var(--ink); color: var(--white); }
.iw-panel-ink .iw-btn-call:focus-visible { outline-color: var(--white); }

/* ---------- Header ---------- */
.iw-header { position: sticky; top: 0; z-index: 50; background: var(--white); border-bottom: 1px solid var(--line); }
.iw-header-in { display: flex; align-items: center; gap: 22px; height: var(--hdr); max-width: 1340px; margin-inline: auto; padding-inline: var(--gut); }
.iw-brand { flex: none; display: block; }
.iw-brand img { height: 46px; width: auto; }
.iw-navcheck { position: absolute; opacity: 0; pointer-events: none; }
.iw-burger { display: none; }
.iw-nav { flex: 1; }
.iw-nav-list { display: flex; justify-content: center; gap: clamp(4px, 1.4vw, 22px); list-style: none; }
.iw-nav-item { position: static; }
.iw-nav-link { display: flex; align-items: center; height: var(--hdr); padding: 0 10px; color: var(--ink); font-weight: 650; font-size: .98rem; text-decoration: none; border-bottom: 3px solid transparent; border-top: 3px solid transparent; }
.iw-nav-link:hover, .iw-has-sub:hover > .iw-nav-link, .iw-has-sub:focus-within > .iw-nav-link { border-bottom-color: var(--orange); }
.iw-has-sub > .iw-nav-link::after { content: ""; width: 7px; height: 7px; margin-left: 8px; margin-top: -4px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg); }
.iw-sub { display: none; position: absolute; left: 0; right: 0; top: 100%; background: var(--white); border-top: 1px solid var(--line); border-bottom: 4px solid var(--orange); box-shadow: 0 30px 50px -30px rgba(10, 27, 38, .45); padding: 28px max(var(--gut), calc((100vw - 1240px) / 2)); grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 24px; }
.iw-has-sub:hover > .iw-sub, .iw-has-sub:focus-within > .iw-sub { display: grid; }
.iw-sub-name { font-family: var(--display); font-weight: 800; font-stretch: 108%; font-size: .92rem; color: var(--orange-d); margin: 0 0 8px; }
.iw-sub a { display: block; padding: 6px 0; color: var(--ink); font-weight: 550; text-decoration: none; }
.iw-sub a:hover { text-decoration: underline; text-decoration-color: var(--orange); text-decoration-thickness: 2px; text-underline-offset: 4px; }
.iw-header-cta { display: flex; gap: 10px; flex: none; }

/* ---------- Stages: the open wall where the pipe shows ---------- */
.iw-stage, .iw-window { position: relative; pointer-events: none; }
.iw-window { display: none; }
/* CSS pipe shown when the 3D scene is not running (no JS, no WebGL) */
.iw-stage::before, .iw-window::before { content: ""; position: absolute; left: 50%; top: -40px; bottom: -40px; width: 46px; margin-left: -23px; background: linear-gradient(90deg, #06131C 0%, #1A2E3C 34%, #0A1B26 70%, #06131C 100%); }
.iw-stage::after, .iw-window::after { content: ""; position: absolute; left: 50%; top: 50%; width: 58px; height: 44px; margin: -22px 0 0 -29px; border-radius: 5px; background: linear-gradient(180deg, var(--orange) 0 32%, var(--orange-d) 32% 68%, var(--orange) 68% 100%); }
.iw-stage-band::before { left: -40px; right: -40px; top: 50%; bottom: auto; width: auto; height: 46px; margin: -23px 0 0; background: linear-gradient(180deg, #06131C 0%, #1A2E3C 34%, #0A1B26 70%, #06131C 100%); }
.iw-stage-band::after { width: 44px; height: 58px; margin: -29px 0 0 -22px; background: linear-gradient(90deg, var(--orange) 0 32%, var(--orange-d) 32% 68%, var(--orange) 68% 100%); }
.iw-stage-hero::before, .iw-stage-hero::after { display: none; }
.iw-3d .iw-stage::before, .iw-3d .iw-stage::after, .iw-3d .iw-window::before, .iw-3d .iw-window::after,
.iw-stills .iw-stage::before, .iw-stills .iw-stage::after, .iw-stills .iw-window::before, .iw-stills .iw-window::after { display: none; }
.iw-still { position: absolute; left: 0; top: 0; width: 100%; height: 100%;
  -webkit-mask-image: linear-gradient(to right, transparent, #000 9%, #000 91%, transparent), linear-gradient(to bottom, transparent, #000 9%, #000 91%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to right, transparent, #000 9%, #000 91%, transparent), linear-gradient(to bottom, transparent, #000 9%, #000 91%, transparent);
  mask-composite: intersect; }

/* ---------- Panels ---------- */
.iw-panel { background: var(--white); border-radius: 12px; padding: clamp(22px, 3vw, 44px); box-shadow: 0 1px 0 rgba(10, 27, 38, .05), 0 26px 44px -30px rgba(10, 27, 38, .42); }
.iw-panel-ink { background: var(--ink); color: var(--white); }
.iw-panel-ink p, .iw-panel-ink li { color: #DCE4E9; }
.iw-panel-ink p a, .iw-panel-ink li a { color: #FF6A3D; }
.iw-panel-ink p a:hover, .iw-panel-ink li a:hover { color: var(--white); }

.iw-sec { padding-block: clamp(44px, 9vh, 104px); }
.iw-split { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); column-gap: var(--gap); align-items: stretch; }
.iw-split > .iw-stage { grid-row: 1; min-height: min(62vh, 600px); }
.iw-split > .iw-panel, .iw-split > .iw-stack { grid-row: 1; align-self: center; }
.iw-split-stage-right > .iw-panel, .iw-split-stage-right > .iw-stack { grid-column: 1 / span 7; }
.iw-split-stage-right > .iw-stage { grid-column: 8 / span 5; }
.iw-split-stage-left > .iw-stage { grid-column: 1 / span 6; }
.iw-split-stage-left > .iw-panel { grid-column: 7 / span 6; }
.iw-split-wide.iw-split-stage-right > .iw-panel, .iw-split-wide.iw-split-stage-right > .iw-stack { grid-column: 1 / span 9; }
.iw-split-wide.iw-split-stage-right > .iw-stage { grid-column: 10 / span 3; }
.iw-stack { display: grid; row-gap: var(--gap); }

/* ---------- 1. Hero ---------- */
.iw-hero { position: relative; display: grid; align-items: center; min-height: calc(100vh - var(--hdr)); min-height: calc(100svh - var(--hdr)); padding-block: 36px 84px; }
.iw-hero-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); column-gap: var(--gap); align-items: center; width: 100%; }
.iw-hero-copy { grid-column: 1 / span 6; }
.iw-stage-hero { grid-column: 7 / span 6; min-height: min(66vh, 620px); display: grid; place-items: center; }
.iw-emblem { width: min(74%, 360px); transition: opacity .5s ease; }
.iw-3d .iw-emblem, .iw-stills .iw-emblem { opacity: 0; }
.iw-live { display: inline-flex; align-items: center; gap: 10px; margin-bottom: 20px; font-weight: 700; font-size: .98rem; }
.iw-live-dot { width: 11px; height: 11px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 0 5px rgba(253, 67, 14, .2); }
.iw-cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin: 30px 0 26px; }
.iw-ticks { display: flex; flex-wrap: wrap; gap: 8px 26px; list-style: none; font-weight: 650; font-size: .98rem; }
.iw-ticks li { display: flex; align-items: center; gap: 9px; }
.iw-ticks li::before { content: ""; width: 9px; height: 15px; margin-top: -4px; border-right: 3px solid var(--orange-d); border-bottom: 3px solid var(--orange-d); transform: rotate(45deg); flex: none; }
.iw-cue { display: none; position: absolute; left: max(var(--gut), calc((100vw - var(--wrap)) / 2 + var(--gut))); bottom: 22px; margin: 0; font-weight: 700; font-size: .92rem; color: var(--mute); padding-bottom: 26px; }
.iw-3d .iw-cue { display: block; }
.iw-cue::after { content: ""; position: absolute; left: 0; bottom: 0; width: 2px; height: 20px; background: var(--orange); transform-origin: top; animation: iw-cue 1.8s ease-in-out infinite; }
@keyframes iw-cue { 0% { transform: scaleY(0); } 50% { transform: scaleY(1); } 100% { transform: scaleY(1) translateY(20px); opacity: 0; } }

/* ---------- 2. Emergency ---------- */
.iw-bigcall { display: inline-flex; flex-direction: column; gap: 4px; margin: 10px 0 30px; color: var(--white); text-decoration: none; }
.iw-bigcall-label { font-weight: 700; font-size: .98rem; color: #FF6A3D; }
.iw-bigcall-num { font-family: var(--display); font-weight: 900; font-stretch: 125%; font-size: clamp(2.1rem, 4.6vw, 3.9rem); line-height: 1; letter-spacing: -.01em; text-decoration: underline; text-decoration-color: var(--orange); text-decoration-thickness: 5px; text-underline-offset: 9px; }
.iw-bigcall:hover .iw-bigcall-num { color: #FF6A3D; }
.iw-until-h { color: var(--white); margin-bottom: 12px; }
.iw-until { list-style: none; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; }
.iw-until li { border-top: 3px solid var(--orange); padding-top: 12px; font-size: .97rem; line-height: 1.5; }
.iw-until strong { display: block; color: var(--white); margin-bottom: 2px; }

/* ---------- 3. Services ---------- */
.iw-services-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); column-gap: var(--gap); align-items: start; }
.iw-stage-sticky { grid-column: 1 / span 4; position: sticky; top: var(--hdr); height: calc(100vh - var(--hdr)); }
.iw-services-col { grid-column: 5 / span 8; display: grid; row-gap: var(--gap); }
.iw-group { padding-top: clamp(20px, 2.4vw, 32px); padding-bottom: 6px; }
.iw-group-name { display: flex; align-items: center; gap: 12px; margin: 0 0 14px; font-family: var(--display); font-weight: 800; font-stretch: 112%; font-size: 1.02rem; color: var(--orange-d); }
.iw-group-name::before { content: ""; width: 26px; height: 16px; border-radius: 3px; background: linear-gradient(90deg, var(--orange) 0 30%, var(--orange-d) 30% 70%, var(--orange) 70% 100%); flex: none; }
.iw-cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 40px; }
.iw-card { border-top: 1px solid var(--line); padding: 22px 0 26px; display: flex; flex-direction: column; }
.iw-card p { font-size: .98rem; line-height: 1.58; color: var(--mute); margin-bottom: 14px; }
.iw-more { margin-top: auto; align-self: flex-start; color: var(--ink); font-weight: 700; font-size: .98rem; text-decoration: underline; text-decoration-color: var(--orange); text-decoration-thickness: 2.5px; text-underline-offset: 6px; }
.iw-more:hover { color: var(--orange-d); }

/* ---------- 4. Local expertise ---------- */
.iw-quads { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 44px; margin-top: 26px; }
.iw-quad { border-top: 1px solid var(--line); padding: 22px 0 24px; }
.iw-quad p { font-size: .99rem; color: var(--mute); }

/* ---------- 5 to 7. Problem sections ---------- */
.iw-problem .iw-panel p { color: var(--mute); }
.iw-problem .iw-btn { margin-top: 12px; }
.iw-fix { list-style: none; counter-reset: fix; margin: 6px 0 20px; display: grid; gap: 12px; }
.iw-fix li { counter-increment: fix; position: relative; padding-left: 46px; color: var(--mute); }
.iw-fix li strong { color: var(--ink); }
.iw-fix li::before { content: counter(fix); position: absolute; left: 0; top: 0; width: 30px; height: 30px; border-radius: 6px; background: var(--ink); color: var(--white); font-family: var(--display); font-weight: 800; font-size: .95rem; display: grid; place-items: center; }

/* ---------- 8. Process ---------- */
.iw-process-head { max-width: 760px; }
.iw-stage-band { height: 190px; }
.iw-steps { list-style: none; counter-reset: step; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 20px; }
.iw-step { counter-increment: step; padding: 24px 22px 26px; }
.iw-step::before { content: counter(step); display: block; font-family: var(--display); font-weight: 900; font-stretch: 125%; font-size: 2.6rem; line-height: 1; color: var(--orange); margin-bottom: 12px; }
.iw-step::after { content: ""; position: absolute; left: 50%; bottom: 100%; width: 3px; height: 34px; margin-left: -1.5px; background: var(--slate); }
.iw-step p { font-size: .96rem; line-height: 1.52; color: var(--mute); }

/* ---------- 9. Trust and questions ---------- */
.iw-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 26px 32px; margin: 26px 0 0; }
.iw-fact { border-top: 3px solid var(--orange); padding-top: 14px; }
.iw-fact dt { font-family: var(--display); font-weight: 900; font-stretch: 118%; font-size: 1.32rem; line-height: 1.1; color: var(--white); margin-bottom: 6px; }
.iw-fact dd { margin: 0; color: var(--mute-ink); font-size: .96rem; line-height: 1.5; }
.iw-qa-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 44px; margin-top: 8px; }
.iw-qa-item { border-top: 1px solid var(--line); padding: 22px 0 24px; }
.iw-qa-item p { color: var(--mute); font-size: .99rem; }

/* ---------- 10. Suburbs ---------- */
.iw-suburbs .iw-panel p { color: var(--mute); }
.iw-split-even.iw-split-stage-left > .iw-stage { grid-column: 1 / span 6; min-height: min(72vh, 680px); }

/* ---------- 11. Quote ---------- */
.iw-form { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px 18px; margin-top: 24px; }
.iw-field { display: grid; gap: 6px; }
.iw-field-full { grid-column: 1 / -1; }
.iw-field label { font-weight: 700; font-size: .95rem; color: var(--white); }
.iw-opt { font-weight: 500; color: var(--mute-ink); }
.iw-field input, .iw-field select, .iw-field textarea { width: 100%; min-height: 50px; padding: 12px 14px; border: 2px solid transparent; border-radius: 8px; background: var(--white); color: var(--ink); font: inherit; font-size: 1rem; }
.iw-field textarea { resize: vertical; min-height: 104px; }
.iw-field input[type="file"] { padding: 10px; background: #13293A; color: #DCE4E9; border: 2px dashed #3C5568; }
.iw-field input:focus-visible, .iw-field select:focus-visible, .iw-field textarea:focus-visible { outline: 3px solid var(--orange); outline-offset: 2px; }
.iw-form-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 14px 22px; margin-top: 6px; }
.iw-form-note { margin: 0; font-weight: 600; font-size: .95rem; }
.iw-form-status { margin: 0; font-weight: 700; }
.iw-form-status:empty { display: none; }
.iw-form-status { padding: 14px 16px; border-radius: 8px; background: #13293A; border-left: 5px solid var(--orange); color: var(--white); }
.iw-quote { padding-bottom: clamp(60px, 12vh, 130px); }

/* ---------- Footer ---------- */
.iw-footer { position: relative; z-index: 1; background: var(--ink); color: #DCE4E9; padding: 64px 0 26px; }
.iw-footer-grid { display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 40px; }
.iw-footer-brand img { height: 52px; width: auto; margin-bottom: 18px; }
.iw-footer-brand p { color: var(--mute-ink); font-size: .96rem; max-width: 36ch; }
.iw-footer-call a { font-family: var(--display); font-weight: 900; font-stretch: 118%; font-size: 1.5rem; color: var(--white); text-decoration: none; }
.iw-footer-call a:hover { color: #FF6A3D; }
.iw-footer-brand .iw-footer-lic { color: var(--white); font-weight: 650; }
.iw-footer-h { font-family: var(--display); font-weight: 800; font-stretch: 108%; color: var(--white); margin-bottom: 12px; }
.iw-footer-col ul { list-style: none; display: grid; gap: 9px; }
.iw-footer-col li a { color: var(--mute-ink); font-weight: 500; font-size: .96rem; text-decoration: none; }
.iw-footer-col li a:hover { color: var(--white); text-decoration: underline; text-decoration-color: var(--orange); }
.iw-footer-base { display: flex; justify-content: space-between; gap: 20px; margin-top: 44px; padding-top: 22px; border-top: 1px solid #23394A; font-size: .9rem; }
.iw-footer-base p { color: var(--mute-ink); margin: 0; }
.iw-footer-base a { color: var(--mute-ink); font-weight: 500; }

/* ---------- Sticky mobile call bar ---------- */
.iw-callbar { display: none; }

/* ---------- Preview notice (only used by the review build) ---------- */
.iw-toast { position: fixed; left: 50%; bottom: 96px; z-index: 80; transform: translate(-50%, 20px); max-width: min(92vw, 520px); padding: 14px 18px; border-radius: 10px; background: var(--ink); color: var(--white); font-weight: 600; font-size: .95rem; box-shadow: 0 18px 40px -18px rgba(10, 27, 38, .7); opacity: 0; pointer-events: none; transition: opacity .2s ease, transform .2s ease; }
.iw-toast.is-on { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Mid widths ---------- */
@media (max-width: 1180px) {
  .iw-nav-link { padding-inline: 6px; font-size: .93rem; }
  .iw-hide-sm { display: none; }
  .iw-steps { gap: 14px; }
  .iw-step { padding: 20px 16px 22px; }
  .iw-cards { column-gap: 28px; }
}

/* ---------- Mobile and tablet: single column, pipe shows in the windows ---------- */
@media (max-width: 899px) {
  html { scroll-padding-top: 76px; }
  .iwsp { --hdr: 64px; font-size: 16.5px; padding-bottom: 76px; }
  .iw-header-in { gap: 10px; }
  .iw-brand img { height: 38px; }
  .iw-header-cta { order: 2; margin-left: auto; }
  .iw-header-cta .iw-btn-call span { display: none; }
  .iw-header-cta .iw-btn-call { padding-inline: 18px; min-width: 52px; }
  .iw-burger { order: 3; display: inline-flex; align-items: center; gap: 9px; min-height: 44px; padding: 0 12px; border-radius: 8px; box-shadow: inset 0 0 0 2px var(--ink); font-weight: 750; font-size: .95rem; cursor: pointer; }
  .iw-burger-bars { width: 18px; height: 12px; border-top: 2px solid var(--ink); border-bottom: 2px solid var(--ink); position: relative; }
  .iw-burger-bars::after { content: ""; position: absolute; left: 0; right: 0; top: 3px; border-top: 2px solid var(--ink); }
  .iw-navcheck:focus-visible + .iw-burger { outline: 3px solid var(--orange); outline-offset: 3px; }
  .iw-navcheck:checked + .iw-burger { background: var(--ink); color: var(--white); }
  .iw-navcheck:checked + .iw-burger .iw-burger-bars, .iw-navcheck:checked + .iw-burger .iw-burger-bars::after { border-color: var(--white); }
  .iw-nav { display: none; position: absolute; left: 0; right: 0; top: 100%; max-height: calc(100vh - var(--hdr) - 74px); max-height: calc(100dvh - var(--hdr) - 74px); overflow: auto; background: var(--white); border-bottom: 4px solid var(--orange); box-shadow: 0 30px 50px -30px rgba(10, 27, 38, .5); padding: 6px var(--gut) 24px; }
